const StateV = { Idle: "idle", Running: "running", Done: "done" } as const;
type State = "idle" | "running" | "done";
const next: Record<State, State[]> = { idle: ["running"], running: ["done"], done: [] };
const labels: { [K in State]: string } = { idle: "i", running: "r", done: "d" };
interface U { id: number; name: string }
function main(): void {
  const users: U[] = [{ id: 1, name: "a" }, { id: 2, name: "b" }];
  console.log(Object.fromEntries(users.map((u) => [u.id, u.name])), Object.fromEntries(users.map((u) => [u.name, u.id])));
  const s: State = StateV.Running;
  console.log(next[StateV.Idle], s, labels[StateV.Done], labels[s]);
}
